package com.nequard.monitoring;
import com.nequard.auth.OrganizationAccessService;import com.nequard.network.Device;import com.nequard.network.DeviceRepository;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/metrics") public class MetricController{private final MetricSnapshotRepository repo;private final DeviceRepository devices;private final OrganizationAccessService access;public MetricController(MetricSnapshotRepository r,DeviceRepository d,OrganizationAccessService a){repo=r;devices=d;access=a;}@GetMapping("/device/{deviceId}")public List<MetricSnapshot> device(Authentication a,@PathVariable UUID deviceId){Device d=devices.findById(deviceId).orElseThrow(()->new NoSuchElementException("DEVICE_NOT_FOUND"));if(!access.canAccess(a,d.getOrganizationId()))throw new SecurityException("TENANT_ACCESS_DENIED");return repo.findTop100ByDeviceIdOrderByRecordedAtDesc(deviceId);}}